/* Ambulatório de clínica médica — conduta, receituário e orientações. ps = conduta no consultório (grupos 'AVALIAÇÃO…' vão para Explicações) */
window.RXC=[
{n:'Hipertensão arterial descontrolada (ambulatório)',cid:'I10',sp:'Cardiometabólico',ps:[{v:'CONDUTA NO CONSULTÓRIO',i:['Confirmar: PA média de 2–3 medidas após 5 min sentado, manguito adequado, braço apoiado; MRPA (3 dias, 2 medidas manhã/noite) ou MAPA antes de escalar se possível (avental branco em 15–30%)','Checar ADESÃO (perguntar sem julgar; posologia simplificada; custo), sal, álcool, AINE, descongestionante, corticoide, anticoncepcional, apneia do sono, ganho de peso','Escalonar em DOSE FIXA COMBINADA (↑ adesão e controle): se monoterapia → dupla (IECA/BRA + BCC ou + tiazídico); se dupla → tripla (IECA/BRA + BCC + tiazídico — ex.: losartana 100 + anlodipino 10 + hidroclorotiazida 25/clortalidona 12,5–25); se tripla em dose plena → HAS RESISTENTE: espironolactona 25–50 mg (PATHWAY-2) e investigar secundária','Meta: < 130/80 (maioria, se tolerado); idoso frágil < 140/90; reavaliar em 2–4 semanas após cada ajuste (efeito pleno em 4 semanas)','Lesão de órgão-alvo/risco: ECG, creatinina + TFG, K, Na, glicemia/HbA1c, lipidograma, ácido úrico, urina I + albuminúria (RAC), fundo de olho se grave; ecocardiograma se ECG alterado/sopro/IC; estratificar risco CV (escore SBC/SCORE2) → estatina se alto risco','Suspeitar de HAS SECUNDÁRIA: início < 30 a ou > 55 a grave, resistente, hipocalemia (hiperaldosteronismo — relação aldosterona/renina), sopro abdominal/piora da função renal com IECA (renovascular), ronco/sonolência (SAOS — polissonografia), crises de palpitação/sudorese/cefaleia (feocromocitoma), fácies cushingoide, pulsos femorais diminuídos (coarctação), creatinina ↑/proteinúria (DRC)']}],casa:[{v:'USO ORAL — ESQUEMA EM COMBINAÇÃO (escolher/ajustar conforme o esquema atual)',i:[['Losartana 50 mg (ou enalapril 10–20 mg / candesartana 8–16 mg / olmesartana 20–40 mg)','60 comprimidos','Tomar 1 comprimido de 12/12 h (losartana) ou 1×/dia pela manhã (outros); dose máxima losartana 100 mg/dia'],['+ Anlodipino 5 mg (aumentar para 10 mg se necessário)','30 comprimidos','Tomar 1 comprimido 1×/dia pela manhã (edema de tornozelo: reduzir/associar IECA)'],['+ Hidroclorotiazida 25 mg (ou clortalidona 12,5–25 mg — mais potente/duradoura; indapamida 1,5 mg)','30 comprimidos','Tomar 1 comprimido pela manhã (controlar K/Na/ácido úrico/glicemia em 4–6 semanas)'],['Espironolactona 25 mg — 4º fármaco (HAS resistente) se K < 4,5 e TFG > 45','30 comprimidos','Tomar 1 comprimido pela manhã; K e creatinina em 1–2 e 4 semanas (ginecomastia: trocar por eplerenona/amilorida)'],['Preferir combinações em comprimido único quando disponíveis (ex.: losartana + HCTZ 50/12,5 ou 100/25; anlodipino + losartana 5/50; valsartana + anlodipino + HCTZ)','30 comprimidos','1 comprimido 1×/dia'],['Atorvastatina 20–40 mg (se risco cardiovascular alto/muito alto, DM, DRC, LOA)','30 comprimidos','Tomar 1 comprimido à noite, uso contínuo'],['AAS 100 mg — APENAS prevenção secundária (IAM/AVC/DAP prévios); não para prevenção primária','30 comprimidos','Tomar 1 comprimido após o almoço']]}],ori:['Tomar os remédios TODOS OS DIAS no mesmo horário, mesmo com a pressão normal e sem sintomas — hipertensão não dói; não parar por conta própria; usar caixa organizadora/alarme; levar a receita/caixas na consulta','Sal: < 5 g/dia (1 colher de chá rasa no total do dia) — tirar o saleiro da mesa, evitar embutidos, enlatados, temperos prontos, salgadinhos, macarrão instantâneo, molhos; dieta DASH (frutas, verduras, grãos integrais, laticínios desnatados, feijões, oleaginosas); perder 5–10% do peso (cada 1 kg ≈ −1 mmHg); atividade física 150 min/semana (caminhada 30 min 5×/semana); álcool: no máximo 1 dose/dia (mulher) ou 2 (homem) — ideal nenhuma; parar de fumar; sono 7–8 h','MRPA em casa: aparelho de braço validado, sentado, 5 min de repouso, 2 medidas pela manhã (antes do remédio) e 2 à noite por 5–7 dias — anotar e trazer; não medir toda hora; média < 130/80 em casa é a meta (135/85 aceitável)','Evitar anti-inflamatórios (diclofenaco, ibuprofeno, nimesulida), descongestionantes (pseudoefedrina/nafazolina), corticoides, anabolizantes e "remédios para emagrecer" — sobem a pressão','Retorno em 4 semanas com MRPA e exames; depois a cada 3–6 meses quando controlado; exames anuais (creatinina, K, glicemia, lipídios, urina, ECG)'],al:['PA ≥ 180/120 COM dor no peito, falta de ar, dor de cabeça muito forte, visão turva, confusão, fraqueza/formigamento de um lado, fala enrolada, sangramento → SAMU 192/PS (emergência hipertensiva)','PA ≥ 180/120 SEM sintomas: repousar 30 min, remedir; se persistir, procurar atendimento no mesmo dia (não tomar várias doses extras)','Tontura ao levantar, desmaio, PA < 100/60 com sintomas (excesso de medicação — reduzir), tosse seca persistente (IECA → trocar por BRA), inchaço de lábios/língua (angioedema por IECA — parar e PS), inchaço de pernas (anlodipino), câimbras/fraqueza (potássio), ginecomastia (espironolactona)'],ref:'Diretrizes Brasileiras de Hipertensão Arterial 2020 (SBC/SBH/SBN) e Diretriz Brasileira de HAS 2025; ESC/ESH 2023 e ESC 2024; ACC/AHA 2017; PATHWAY-2 Lancet 2015 (espironolactona na resistente); SPRINT NEJM 2015 (meta intensiva); TRIUMPH/QUARTET (combinação fixa em baixas doses); Cochrane 2018 (combinação fixa e adesão).'},
{n:'Diabetes tipo 2 descontrolado (ambulatório)',cid:'E11.65',sp:'Cardiometabólico',ps:[{v:'CONDUTA NO CONSULTÓRIO',i:['Definir o descontrole: HbA1c acima da meta (< 7% na maioria; < 7,5–8% em idoso frágil/hipoglicemias; < 6,5% em jovem sem comorbidade) ou glicemia de jejum > 130 / pós-prandial > 180; verificar adesão, dieta, atividade, ganho de peso, infecção, corticoide, depressão, custo','Sintomas de hiperglicemia (polis, perda de peso) com HbA1c > 10% ou glicemia > 300: INICIAR INSULINA basal (NPH 10 UI ou 0,1–0,2 UI/kg ao deitar; titular +2 UI a cada 3 dias até jejum 80–130) + manter metformina; se cetose/vômitos → PS','Sem sintomas: INTENSIFICAR — 1) metformina até 2.000 mg/dia (XR se intolerância); 2) adicionar conforme perfil: DCV aterosclerótica/IC/DRC → iSGLT2 (dapagliflozina/empagliflozina — SUS para DM2 com DCV ≥ 65 a) ou aGLP-1 (semaglutida/liraglutida/dulaglutida); obesidade → aGLP-1 ou tirzepatida; custo → gliclazida MR 30–120 mg (menor hipoglicemia que glibenclamida) ou pioglitazona 15–45 mg (não em IC); iDPP-4 (sitagliptina/linagliptina — neutro); 3) se HbA1c > 1,5% acima da meta → dupla já no início; 4) falha com 2–3 orais → insulina basal → basal-plus/basal-bolus ou aGLP-1 + basal','Rastrear complicações/comorbidades ANUALMENTE: HbA1c a cada 3 meses até a meta (depois 6), creatinina/TFG + RAC (albuminúria), lipidograma, fundo de olho (retinografia), exame dos pés (monofilamento/pulsos/calçado), PA, peso/IMC, TGO/TGP (MASLD), B12 se metformina > 4 anos, ECG; vacinas (influenza, pneumocócica, hepatite B, Covid, zóster)','Tratar o RISCO CV em conjunto: estatina para todos ≥ 40 anos (atorvastatina 20–80 conforme risco; LDL < 70 alto risco / < 50 muito alto), PA < 130/80 (IECA/BRA se albuminúria), cessar tabagismo; AAS só em prevenção secundária','Educação: automonitorização (jejum e pré-jantar; mais se insulina), hipoglicemia (reconhecer/tratar — regra dos 15), dias de doença, pés; nutricionista; programa de atividade; saúde mental (depressão/diabetes distress ↓ adesão)']}],casa:[{v:'USO ORAL / SC — ESCOLHER CONFORME O ESQUEMA ATUAL',i:[['Metformina 850 mg (ou 500 mg / XR 500–1.000 mg)','60 comprimidos','Tomar 1 comprimido no café e 1 no jantar (titular em 1–2 semanas até 2.000 mg/dia; com as refeições; suspender em vômitos/diarreia/contraste; TFG < 30: não usar)'],['+ Dapagliflozina 10 mg ou Empagliflozina 10–25 mg (se DCV, IC, DRC, obesidade — ↓ eventos CV/renais)','30 comprimidos','Tomar 1 comprimido pela manhã (hidratação; higiene genital; suspender se jejum prolongado/cirurgia/infecção grave — cetoacidose euglicêmica; TFG ≥ 20–25)'],['OU/+ Semaglutida SC 0,25 mg/sem × 4 → 0,5 mg → 1 mg (ou liraglutida 0,6 → 1,2–1,8 mg/dia; dulaglutida 0,75–1,5 mg/sem; tirzepatida 2,5 → 5–15 mg/sem)','1 caneta','Aplicar 1×/semana SC (abdome/coxa), qualquer horário; náusea é comum no início (refeições menores); não em gestação/CMT/pancreatite'],['OU Gliclazida MR 30 mg (opção de baixo custo; ↑ para 60–120 mg)','30 comprimidos','Tomar 1–4 comprimidos no café da manhã (risco de hipoglicemia — não pular refeições; evitar glibenclamida em idosos/DRC)'],['OU Sitagliptina 100 mg (ou linagliptina 5 mg — sem ajuste renal) — idoso/risco de hipoglicemia','30 comprimidos','Tomar 1 comprimido 1×/dia (não associar a aGLP-1)'],['Insulina NPH 100 UI/mL (frasco/caneta) + seringas 100 UI/agulhas 4–6 mm + glicosímetro/tiras/lancetas','1–2 frascos ou canetas','Aplicar ___ UI SC às 22 h (iniciar 10 UI ou 0,2 UI/kg); AUMENTAR 2 UI a cada 3 dias se glicemia de jejum > 130 por 3 dias; REDUZIR 4 UI (ou 10–20%) se < 70; se precisar > 0,5 UI/kg ou pós-prandial alta → acrescentar insulina regular/rápida nas refeições (basal-plus)'],['Atorvastatina 20 mg (40–80 se DCV/alto risco)','30 comprimidos','Tomar 1 comprimido à noite, uso contínuo'],['Losartana 50 mg (ou enalapril 10 mg) — se PA ≥ 130/80 ou albuminúria','30–60 comprimidos','Tomar 1 comprimido 1–2×/dia'],['Tiras reagentes (SUS — Lei 11.347 para usuários de insulina)','100–150 tiras','Medir glicemia em jejum e antes do jantar diariamente (se insulina); 2–3×/semana em horários variados (se só oral); anotar']]}],ori:['Alimentação: reduzir açúcar, refrigerante/suco (mesmo natural em excesso), doces, pão branco/massas/arroz em grande quantidade; priorizar verduras, legumes, proteínas magras, feijões, grãos integrais; prato: ½ salada/vegetais, ¼ proteína, ¼ carboidrato; refeições regulares (não pular, sobretudo com insulina/gliclazida); perder 5–10% do peso melhora muito o controle (e pode levar à remissão); nutricionista','Atividade física: 150 min/semana de caminhada/aeróbico + força 2×/semana — reduz a glicemia tanto quanto um remédio; checar os pés antes/depois; carregar açúcar se usar insulina/gliclazida','Hipoglicemia (< 70; tremor, suor, fome, confusão): 15 g de açúcar (1 colher de sopa/150 mL de suco/3 balas), remedir em 15 min, repetir se preciso, depois lanche; anotar e avisar (ajustar dose); nunca dirigir com glicemia < 90','Insulina: rodízio de locais, guardar na geladeira (em uso: 28–30 dias em temperatura ambiente), aplicar no horário, não reutilizar agulha muitas vezes; ajuste pela tabela (jejum > 130 → +2 UI a cada 3 dias)','Pés: olhar todos os dias (feridas, bolhas, cor), hidratar (não entre os dedos), cortar unhas retas, não andar descalço, sapato fechado confortável; dentista 2×/ano; parar de fumar; vacinas em dia; retorno em 4–8 semanas com as glicemias anotadas e HbA1c em 3 meses'],al:['Glicemia > 300 persistente com sede/urina excessiva, vômitos, dor abdominal, respiração rápida, hálito adocicado, sonolência (cetoacidose/hiperosmolar) → PS','Hipoglicemia com desmaio/convulsão ou que se repete (> 2/semana) → reduzir dose/procurar atendimento','Ferida no pé que não cicatriza, pé vermelho/quente/inchado, dor em repouso nas pernas, visão turva súbita, dor no peito, fraqueza de um lado do corpo, febre/infecção que não melhora, dor para urinar (ITU/candidíase com iSGLT2)'],ref:'Diretriz da Sociedade Brasileira de Diabetes 2023/2024 (tratamento farmacológico do DM2; insulinização); ADA Standards of Care 2024/2025; ADA/EASD Consensus 2022; KDIGO Diabetes in CKD 2022; UKPDS; EMPA-REG/CANVAS/DECLARE/DAPA-HF/CREDENCE; LEADER/SUSTAIN-6/REWIND; SURPASS; ACCORD/ADVANCE/VADT (metas individualizadas); Conitec 2023 (dapagliflozina no SUS).'},
{n:'Dislipidemia (colesterol alto / triglicerídeos altos)',cid:'E78.5 / E78.1',sp:'Cardiometabólico',ps:[{v:'CONDUTA NO CONSULTÓRIO',i:['ESTRATIFICAR O RISCO (define a meta e a intensidade): MUITO ALTO — DCV aterosclerótica (IAM, AVC/AIT, DAP, revascularização, placa obstrutiva ≥ 50%): meta LDL < 50 e ↓ ≥ 50%; ALTO — DM com LOA/fatores, DRC 3–4, LDL ≥ 190, hipercolesterolemia familiar, escore de risco alto, aterosclerose subclínica (CAC > 100): LDL < 70; INTERMEDIÁRIO: LDL < 100; BAIXO: LDL < 130 (SBC 2017/2019; ESC 2019/2021: calculadora SCORE2)','Excluir causas secundárias antes/junto: TSH (hipotireoidismo), glicemia/HbA1c, creatinina/TFG, urina (síndrome nefrótica), TGO/TGP/GGT (colestase, álcool, MASLD), medicamentos (tiazídico, betabloqueador, corticoide, isotretinoína, antirretroviral, antipsicótico, estrogênio oral, ciclosporina), gestação; perfil sem jejum é aceitável (jejum de 12 h se TG > 400)','ESTATINA é a base (não "dieta primeiro" em alto risco): alta intensidade — atorvastatina 40–80 / rosuvastatina 20–40 (↓ LDL ≥ 50%); moderada — atorvastatina 10–20 / rosuvastatina 5–10 / sinvastatina 20–40 (sinvastatina 80: proibida — miopatia); não atingiu a meta em 4–12 semanas → dobrar (cada duplicação ↓ 6%) → associar EZETIMIBA 10 mg (↓ 20%; IMPROVE-IT) → inibidor de PCSK9 (alirocumabe/evolocumabe — muito alto risco refratário/HF) ou ácido bempedoico/inclisirana','TRIGLICERÍDEOS: 150–499 → mudança de estilo de vida (açúcar/álcool/carboidrato refinado, peso, exercício), controlar DM, estatina se risco; icosapent etil 2 g 12/12 h em alto risco com TG 135–499 em estatina (REDUCE-IT); ≥ 500 (risco de pancreatite) → FIBRATO (fenofibrato 160–200 mg — preferível com estatina; ciprofibrato 100 mg; evitar genfibrozila + estatina), dieta muito pobre em gordura, abstinência de álcool, ômega-3 2–4 g/dia; ≥ 1.000 → urgência (jejum relativo, internar se dor abdominal)','Monitorar: lipidograma + TGO/TGP (CK só se sintomas musculares) em 4–12 semanas após iniciar/ajustar, depois anual; TGO/TGP > 3× LSN → suspender/reduzir; mialgia: dosar CK, pausar 2–4 sem e reintroduzir outra estatina/dose menor/dias alternados (rosuvastatina 5–10 mg 3×/sem) + ezetimiba; a maioria das "intolerâncias" é nocebo (SAMSON)','Suspeitar de HIPERCOLESTEROLEMIA FAMILIAR: LDL ≥ 190 (adulto) ou ≥ 160 (criança), xantomas tendíneos, arco corneano < 45 a, DCV precoce (< 55 H/< 60 M) pessoal/familiar — escore holandês (DLCN), rastreio em cascata dos familiares, meta mais agressiva/PCSK9; considerar escore de cálcio coronário (CAC) para refinar risco intermediário']}],casa:[{v:'USO ORAL',i:[['Atorvastatina 40 mg (alto risco/DCV: 40–80 mg; risco intermediário: 10–20 mg) — ou Rosuvastatina 20 mg (10–40 mg) / Sinvastatina 40 mg (moderada)','30 comprimidos','Tomar 1 comprimido à noite (atorvastatina/rosuvastatina: qualquer horário), TODOS OS DIAS, uso contínuo (não é "tratamento de 30 dias")'],['+ Ezetimiba 10 mg — se não atingir a meta com estatina em dose máxima tolerada em 4–12 semanas','30 comprimidos','Tomar 1 comprimido 1×/dia junto com a estatina (há combinação fixa: atorvastatina/ezetimiba, rosuvastatina/ezetimiba)'],['Fenofibrato 200 mg (ou 160 mg micronizado; ciprofibrato 100 mg) — SOMENTE triglicerídeos ≥ 500 mg/dL (ou 200–499 persistente em alto risco após estatina)','30 cápsulas','Tomar 1 cápsula 1×/dia após o jantar (ajustar na DRC; não associar genfibrozila a estatina)'],['Ômega-3 (EPA/DHA) 1.000 mg — TG ≥ 500 como adjuvante (2–4 g/dia de EPA+DHA); icosapent etil 2 g 12/12 h se disponível','60–120 cápsulas','Tomar 2 cápsulas de 12/12 h com as refeições'],['Exames de controle: lipidograma (CT, HDL, LDL, TG, não-HDL), TGO/TGP, glicemia/HbA1c, TSH, creatinina — em 4–12 semanas','—','Levar o resultado ao retorno']]}],ori:['A estatina é para USO CONTÍNUO, por anos — o benefício (↓ infarto/AVC em 20–25% a cada 39 mg/dL de LDL) depende de manter; não parar quando o colesterol "normalizar" nem por "medo do fígado/músculo" sem conversar (dores musculares leves muitas vezes não são da estatina — avaliamos)','Alimentação (padrão mediterrâneo/DASH): reduzir gordura saturada (carnes gordas, pele de frango, embutidos, manteiga, queijos amarelos, leite integral, fast-food), evitar gordura trans (biscoitos recheados, margarinas duras, sorvetes industrializados), aumentar fibras (aveia, feijões, frutas com casca, verduras), peixes 2×/semana, azeite, oleaginosas (1 punhado/dia), evitar açúcar/refrigerante/álcool (principalmente se triglicerídeos altos); fitosteróis 2 g/dia (↓ LDL ~10%) opcional','Exercício: 150–300 min/semana aeróbico + força 2×/sem (↑ HDL, ↓ TG); perder 5–10% do peso (↓ TG 20%); parar de fumar (↑ HDL, principal fator modificável de risco CV); controlar PA e diabetes','Efeitos possíveis: dor muscular (geralmente simétrica, grandes músculos, nas 1ªs semanas — avisar; não suspender sozinho), elevação leve de enzimas hepáticas (sem importância se < 3×), ↑ pequeno de glicemia (benefício supera); não usar com suco de toranja/grapefruit em excesso (sinvastatina/atorvastatina); informar outros medicamentos (antifúngicos azólicos, macrolídeos, verapamil/diltiazem, amiodarona, ciclosporina, fibrato — interação)','Exames em 4–12 semanas após iniciar/ajustar, depois 1×/ano; retorno com os exames; filhos/irmãos devem dosar colesterol se LDL ≥ 190 ou infarto precoce na família (hipercolesterolemia familiar)'],al:['Dor/fraqueza muscular INTENSA e generalizada, urina escura ("coca-cola"), febre, cansaço extremo (rabdomiólise — raro) → suspender e procurar atendimento','Olhos/pele amarelos, urina escura, dor no fígado, náuseas persistentes (hepatite — raro)','Dor abdominal intensa irradiada para as costas com vômitos (pancreatite — triglicerídeos muito altos) → PS','Dor no peito, falta de ar ao esforço, dor nas pernas ao andar, fraqueza/fala alterada súbita (eventos cardiovasculares — SAMU 192)'],ref:'Atualização da Diretriz Brasileira de Dislipidemias e Prevenção da Aterosclerose — SBC 2017 e Atualização 2019/2021 (estratificação e metas); Diretriz Brasileira de Hipercolesterolemia Familiar 2021; ESC/EAS Dyslipidaemias 2019 e ESC CVD Prevention 2021 (SCORE2); ACC/AHA 2018/2019; CTT Lancet 2010/2019 (meta-análises de estatinas); IMPROVE-IT NEJM 2015; FOURIER/ODYSSEY OUTCOMES; REDUCE-IT NEJM 2019; SAMSON NEJM 2020 (nocebo); Cochrane 2013 (estatinas em prevenção primária).'},
{n:'Esteatose hepática (gordura no fígado — MASLD/DHGNA)',cid:'K76.0',sp:'Cardiometabólico',ps:[{v:'CONDUTA NO CONSULTÓRIO',i:['Diagnóstico: esteatose à imagem (USG — sensível só se > 20–30% de gordura; TC/RM-PDFF) ou enzimas alteradas + ≥ 1 critério cardiometabólico (IMC ≥ 25 ou circunferência ↑, glicemia alterada/DM2, PA ≥ 130/85, TG ≥ 150, HDL baixo) = MASLD (nova nomenclatura 2023); EXCLUIR outras causas: álcool (> 20 g/dia M / 30 g H → MetALD/doença alcoólica; AUDIT-C), hepatites B e C (HBsAg, anti-HCV — sempre), medicamentos (amiodarona, metotrexato, tamoxifeno, corticoide, valproato, antirretrovirais), hemocromatose (ferritina/saturação de transferrina), autoimune (FAN, anti-músculo liso, IgG) e Wilson/deficiência de α1-AT em jovens, doença celíaca, hipotireoidismo (TSH)','ESTRATIFICAR FIBROSE (é o que define prognóstico, não a esteatose): calcular FIB-4 (idade, TGO, TGP, plaquetas — em todo paciente com MASLD/DM2/obesidade): < 1,3 (< 2,0 se > 65 a) = baixo risco → cuidado primário, repetir em 1–3 anos; 1,3–2,67 = indeterminado → ELASTOGRAFIA (FibroScan®: < 8 kPa baixo; 8–12 indeterminado; > 12 alto) ou ELF; > 2,67 = alto risco → hepatologista (fibrose avançada F3–F4: rastreio de CHC com USG + AFP a cada 6 meses, varizes)','TRATAMENTO = PERDA DE PESO + controle cardiometabólico: ↓ 5% do peso melhora esteatose, ≥ 7–10% resolve esteato-hepatite e regride fibrose (dieta mediterrânea com déficit de 500–1.000 kcal/dia, eliminar bebidas açucaradas/frutose/ultraprocessados, café 2–3 xícaras/dia é protetor, exercício aeróbico + resistido 150–300 min/sem — melhora mesmo sem perder peso); ABSTINÊNCIA ou mínimo de álcool; vacinar hepatite A e B','FARMACOTERAPIA (quando esteato-hepatite/fibrose ≥ F2 ou comorbidade que a indique): DM2 → PIOGLITAZONA 15–45 mg (melhora histologia; ganho de peso/edema/IC) ou aGLP-1 (semaglutida 2,4 mg/sem — resolve NASH; liraglutida) ou TIRZEPATIDA (SYNERGY-NASH) / iSGLT2 (melhora enzimas/gordura); sem DM → semaglutida (ESSENCE 2024: ↓ fibrose) ou vitamina E 800 UI/dia (PIVENS — não diabético, sem cirrose; ↑ risco de Ca próstata/AVC hemorrágico discutido); RESMETIROM 80–100 mg (FDA 2024 — F2–F3; não disponível no Brasil); cirurgia bariátrica se IMC ≥ 35 (resolve NASH em 85%); metformina, UDCA, silimarina, ômega-3: NÃO melhoram histologia','ESTATINA É SEGURA e indicada pelo risco CV (principal causa de morte na MASLD) mesmo com TGO/TGP até 3× LSN — não suspender; tratar HAS (IECA/BRA), DM, dislipidemia, SAOS; evitar hepatotóxicos desnecessários (paracetamol até 2 g/dia é seguro)','Seguimento: TGO/TGP, GGT, plaquetas, glicemia/HbA1c, lipidograma, peso/circunferência a cada 6–12 meses; FIB-4 anual (DM2/obesidade: anual; baixo risco: 2–3 anos); encaminhar ao hepatologista se FIB-4 > 2,67, elastografia > 8–12 kPa, plaquetas < 150.000, sinais de hepatopatia crônica, enzimas > 3× persistentes ou dúvida diagnóstica (biópsia)']}],casa:[{v:'USO ORAL / SC (quando indicado — a base é peso/dieta/exercício)',i:[['Pioglitazona 15 mg (↑ 30–45 mg) — DM2 ou pré-DM com esteato-hepatite/fibrose','30 comprimidos','Tomar 1 comprimido 1×/dia (não usar em IC, risco de fratura/edema; ganho de 2–4 kg esperado)'],['OU Semaglutida SC 0,25 mg/sem → 0,5 → 1 → (2,4 mg se obesidade) — ou Liraglutida 0,6 → 1,8–3 mg/dia / Tirzepatida 2,5 → 5–15 mg/sem','1 caneta','Aplicar 1×/semana SC, escalonando a cada 4 semanas conforme tolerância (náusea)'],['OU Vitamina E 400 UI (alfa-tocoferol) — NÃO diabético, sem cirrose, com esteato-hepatite comprovada/fibrose','60 cápsulas','Tomar 1 cápsula de 12/12 h (800 UI/dia) por 1–2 anos com reavaliação (discutir riscos)'],['Dapagliflozina 10 mg / Empagliflozina 10 mg — se DM2 (reduz gordura hepática e eventos CV/renais)','30 comprimidos','Tomar 1 comprimido pela manhã'],['Atorvastatina 20–40 mg — MANTER/iniciar conforme risco CV (segura até TGO/TGP 3× LSN)','30 comprimidos','Tomar 1 comprimido à noite'],['Vacinas hepatite A (2 doses 0–6 m) e hepatite B (3 doses 0-1-6 m) — se suscetível','UBS/CRIE','Conforme sorologias'],['Exames: TGO, TGP, GGT, FA, bilirrubinas, hemograma com plaquetas, albumina, INR, glicemia/HbA1c, insulina, lipidograma, TSH, ferritina/saturação de transferrina, HBsAg, anti-HBc, anti-HCV, creatinina, urina (RAC); USG de abdome superior; elastografia hepática (FibroScan®) se FIB-4 ≥ 1,3','—','Calcular FIB-4 e levar ao retorno em 3–6 meses']]}],ori:['A gordura no fígado é reversível e o tratamento principal é PERDER PESO: meta de 7–10% do peso em 6–12 meses (ex.: 90 kg → perder 6–9 kg), de forma gradual (0,5–1 kg/semana); dieta tipo mediterrânea: muitas verduras/legumes/frutas inteiras, feijões, grãos integrais, azeite, peixes, oleaginosas; CORTAR refrigerantes, sucos (inclusive naturais em excesso), doces, frutose/xarope de milho, ultraprocessados, frituras, carnes processadas; reduzir pão branco/arroz/massas; café (2–3 xícaras/dia, sem açúcar) é protetor; nutricionista','ÁLCOOL: idealmente zero (qualquer quantidade piora; cerveja/vinho/destilado contam igual); nunca em "binge"','EXERCÍCIO: 150–300 min/semana (caminhada rápida, bicicleta, natação) + musculação 2–3×/semana — reduz a gordura do fígado mesmo antes de emagrecer; diminuir o tempo sentado','Evitar remédios/chás "para o fígado" ("hepatoprotetores", silimarina, chás detox, suplementos de musculação, anabolizantes) — não funcionam e alguns intoxicam o fígado; paracetamol até 2 g/dia é seguro; informar qualquer medicação nova; não parar a estatina por "fígado" (ela é segura e protege o coração — a principal causa de morte nesses pacientes)','Vacinar contra hepatite A e B; controlar diabetes, pressão, colesterol, apneia do sono; retorno em 3–6 meses com exames e peso; elastografia/hepatologista se indicado; USG a cada 6 meses apenas se cirrose/fibrose avançada (rastreio de câncer)'],al:['Olhos/pele amarelos, urina escura, fezes claras, barriga inchada (ascite), inchaço de pernas, vômito com sangue/fezes pretas, confusão/sonolência, sangramentos fáceis — sinais de cirrose descompensada → PS','Dor forte no abdome superior direito com febre (vesícula/colangite); perda de peso involuntária rápida, massa abdominal, dor persistente (investigar)','Enzimas hepáticas > 3× o limite, plaquetas em queda, FIB-4 > 2,67 → hepatologista'],ref:'AASLD Practice Guidance NAFLD 2023 (Rinella); EASL–EASD–EASO Clinical Practice Guidelines MASLD 2024; Rinella Hepatology 2023 (nomenclatura MASLD — Delphi); SBH — Diretriz Brasileira de DHGNA 2022/2023 (Sociedade Brasileira de Hepatologia); AGA Clinical Care Pathway 2021 (Kanwal — FIB-4/elastografia); PIVENS NEJM 2010 (vitamina E/pioglitazona); Newsome NEJM 2021 (semaglutida NASH); ESSENCE NEJM 2024/2025; SYNERGY-NASH NEJM 2024 (tirzepatida); MAESTRO-NASH NEJM 2024 (resmetirom); Vilar-Gomez Gastroenterology 2015 (perda de peso e histologia); Musso Diabetologia 2012 (pioglitazona meta-análise).'},
{n:'Obesidade / sobrepeso com comorbidade',cid:'E66.9',sp:'Cardiometabólico',ps:[{v:'CONDUTA NO CONSULTÓRIO',i:['Avaliar: IMC (sobrepeso 25–29,9; obesidade I 30–34,9; II 35–39,9; III ≥ 40), circunferência abdominal (≥ 80 M / ≥ 94 H — risco ↑; ≥ 88/102 — muito ↑), PA, comorbidades (DM2/pré-DM, HAS, dislipidemia, MASLD, SAOS — STOP-BANG, osteoartrite, SOP, DRGE, depressão, incontinência, infertilidade), história ponderal/tentativas, padrão alimentar (compulsão — TCAP, beliscar, noturno), atividade, sono, medicamentos obesogênicos (corticoide, antipsicóticos, antidepressivos tricíclicos/mirtazapina/paroxetina, insulina/sulfonilureia, pioglitazona, anticonvulsivantes, betabloqueador, anti-histamínico), causas secundárias (hipotireoidismo — TSH; Cushing se suspeita clínica); exames: glicemia/HbA1c, lipidograma, TGO/TGP, creatinina, ácido úrico, TSH, ECG se > 40 a','Meta realista e combinada: perder 5–10% do peso em 6 meses (melhora PA, glicemia, lipídios, esteatose, apneia, artrose) — ≥ 10–15% para remissão de DM2/MASLD/SAOS; abordagem sem culpa/estigma, focada em saúde e não só na balança','BASE (para todos): déficit calórico de 500–750 kcal/dia com padrão sustentável (mediterrâneo/DASH/baixo carboidrato — o melhor é o que o paciente mantém), reduzir ultraprocessados/bebidas açucaradas/álcool, proteína 1,2–1,6 g/kg para preservar massa magra, atividade física 150–300 min/semana aeróbica + força 2–3×/sem, sono 7–9 h, terapia cognitivo-comportamental/automonitoramento (diário alimentar/app), nutricionista + educador físico + psicologia (equipe)','FARMACOTERAPIA (IMC ≥ 30, ou ≥ 27 com comorbidade, após/junto com estilo de vida; uso prolongado, como doença crônica): 1ª escolha quando acessível — aGLP-1/duplo agonista: SEMAGLUTIDA 2,4 mg/sem (Wegovy® — ↓ 15%; STEP; ↓ eventos CV — SELECT), TIRZEPATIDA 5–15 mg/sem (Mounjaro® — ↓ 20%; SURMOUNT), LIRAGLUTIDA 3 mg/dia (Saxenda® — ↓ 8%); opções de menor custo (Anvisa): SIBUTRAMINA 10–15 mg (↓ 4–5%; contraindicada em DCV/HAS não controlada/≥ 65 a — receita B2), ORLISTATE 120 mg 3×/dia (↓ 3%; efeitos GI), BUPROPIONA + NALTREXONA 360/32 mg (↓ 5%; compulsão/tabagismo/depressão; não em epilepsia/opioides), TOPIRAMATO (off-label, 50–100 mg; teratogênico/cognitivo), metformina em pré-DM/SOP/antipsicótico (↓ 2–3%); reavaliar em 12–16 semanas: se < 5% de perda → trocar','CIRURGIA BARIÁTRICA/METABÓLICA (CFM 2022/IFSO-ASMBS 2022): IMC ≥ 40, ou ≥ 35 com comorbidade, ou ≥ 30 com DM2 de difícil controle (metabólica, caso a caso) — após falha de tratamento clínico ≥ 2 anos, avaliação multiprofissional (bypass gástrico em Y de Roux/sleeve — ↓ 25–35% do peso, remissão de DM2 em 60–80%, ↓ mortalidade); balão intragástrico/endoscópicos como ponte','Tratar comorbidades em paralelo (HAS, DM — preferir fármacos que ↓ peso: metformina, iSGLT2, aGLP-1; dislipidemia; SAOS — CPAP; esteatose); trocar medicamentos obesogênicos quando possível; rastrear transtorno alimentar/depressão (encaminhar); crianças/adolescentes: pediatria/endocrino (semaglutida ≥ 12 a aprovada)']}],casa:[{v:'USO SC / ORAL (quando indicado — junto com dieta, exercício e acompanhamento)',i:[['Semaglutida 2,4 mg (Wegovy®) SC — caneta 0,25 → 0,5 → 1 → 1,7 → 2,4 mg (escalonar a cada 4 semanas); ou Ozempic® 0,25 → 1 mg (off-label para obesidade)','1 caneta/mês','Aplicar 1×/semana SC no abdome/coxa/braço, mesmo dia da semana; aumentar a dose a cada 4 semanas conforme tolerância; náusea/refluxo: refeições menores, evitar gordura; manter por tempo prolongado (a suspensão leva à recuperação do peso)'],['OU Tirzepatida (Mounjaro®) SC 2,5 mg/sem × 4 → 5 mg → 7,5 → 10 → 12,5 → 15 mg (a cada 4 sem conforme resposta)','1 caixa (4 canetas)/mês','Aplicar 1×/semana SC'],['OU Liraglutida 3 mg (Saxenda®) SC — 0,6 mg/dia e ↑ 0,6 mg a cada semana até 3 mg','3–5 canetas/mês','Aplicar 1×/dia SC, qualquer horário'],['OU Sibutramina 10 mg (↑ 15 mg se perda < 2 kg em 4 semanas) — sem DCV/HAS descontrolada/arritmia/AVC/< 18 ou ≥ 65 a; receita B2','30 cápsulas','Tomar 1 cápsula pela manhã; medir PA e FC a cada consulta; suspender se PA/FC ↑ ou perda < 5% em 3 meses'],['OU Orlistate 120 mg','90 cápsulas','Tomar 1 cápsula junto às 3 principais refeições (com gordura) — esteatorreia se exceder gordura; polivitamínico à noite (A, D, E, K)'],['OU Bupropiona XL 150 mg + Naltrexona 50 mg (ou Contrave® 8/90 mg: 1 cp → até 2 cp 12/12 h) — compulsão/beliscar/tabagismo/depressão','30 + 30 comprimidos','Bupropiona 1 cp pela manhã (↑ para 2 após 1 semana) + naltrexona ½ cp pela manhã (↑ 1 cp); não usar com opioides/epilepsia/bulimia'],['Metformina 500–850 mg (pré-diabetes, SOP, ganho de peso por antipsicótico)','60 comprimidos','Tomar 1 comprimido no café e 1 no jantar (↑ até 2 g/dia)'],['Polivitamínico/mineral (se dieta < 1.200 kcal, orlistate ou pós-bariátrica — esquema específico)','30 comprimidos','Tomar 1 comprimido 1×/dia'],['Encaminhamentos: nutricionista, educador físico/fisioterapia, psicologia (TCC), endocrinologia/cirurgia bariátrica (se critérios), polissonografia (se ronco/sonolência)','—','—']]}],ori:['Obesidade é uma doença crônica (não falta de força de vontade): o tratamento é contínuo e combina alimentação, atividade física, sono, saúde mental e, quando indicado, medicamento ou cirurgia; a meta inicial é perder 5–10% do peso em 6 meses (ex.: 100 kg → 90–95 kg), devagar (0,5–1 kg/semana); manter a perda é tão importante quanto perder','ALIMENTAÇÃO: comer com horário e sem pressa (20 min, mastigar bem, sem telas), prato com metade de verduras/legumes, ¼ proteína (frango, peixe, ovos, feijão, carne magra), ¼ carboidrato integral; água em vez de refrigerante/suco/álcool (líquidos com caloria são a maior "pegadinha"); cortar ultraprocessados (salgadinhos, biscoitos, embutidos, fast-food), doces e frituras; café da manhã proteico; não "pular" refeições (leva a compulsão); lista de compras e planejar as refeições; diário alimentar (app) nas primeiras semanas','MOVIMENTO: começar com o que for possível (10 min de caminhada 3×/dia) e progredir até 150–300 min/semana + musculação 2–3×/semana (preserva músculo, acelera metabolismo); reduzir tempo sentado (levantar a cada hora); escolher algo que goste e seja viável','SONO 7–9 h (privação de sono aumenta fome/ganho de peso), tratar ronco/apneia; manejo do estresse/ansiedade e da "fome emocional" (psicologia — TCC tem evidência); pesar-se 1×/semana no mesmo horário; medir a cintura mensalmente','MEDICAMENTO (se prescrito): é para uso prolongado, sob acompanhamento; efeitos comuns: náusea/refluxo/constipação (aGLP-1 — refeições menores, hidratação, fibras), boca seca/insônia/↑ PA (sibutramina), fezes oleosas (orlistate); NUNCA usar "fórmulas para emagrecer" manipuladas com anfetaminas/hormônio tireoidiano/diuréticos/laxantes, nem comprar canetas sem receita/origem; retorno em 4–8 semanas e depois a cada 2–3 meses'],al:['Dor abdominal intensa e persistente irradiando para as costas com vômitos (pancreatite — aGLP-1), dor no quadrante superior direito (colelitíase — perda rápida de peso), vômitos persistentes/desidratação','Palpitações, PA alta, dor no peito, dor de cabeça intensa, agitação/insônia grave (sibutramina/bupropiona); convulsão; pensamentos de morte/humor muito deprimido (bupropiona/naltrexona, ou pela própria condição)','Perda de peso muito rápida (> 1,5 kg/semana por várias semanas) com fraqueza/queda de cabelo/tontura; sinais de desnutrição; sonolência diurna intensa/pausas respiratórias no sono (apneia não tratada)'],ref:'ABESO — Diretrizes Brasileiras de Obesidade 2016 e Posicionamento 2022/2024 (farmacoterapia); SBEM/ABESO; AACE/ACE Obesity Guidelines 2016 e 2023 (Garvey); Obesity Canada 2020/2022; EASO 2024; STEP 1 NEJM 2021 (semaglutida 2,4); SELECT NEJM 2023; SURMOUNT-1 NEJM 2022 (tirzepatida); SCALE NEJM 2015 (liraglutida); SCOUT NEJM 2010 (sibutramina — restrições); COR-I Lancet 2010 (naltrexona/bupropiona); XENDOS 2004 (orlistate); Look AHEAD NEJM 2013; IFSO/ASMBS 2022 e Resolução CFM 2.429/2022 (bariátrica); SOS NEJM 2007; Cochrane 2016 (dieta/exercício/comportamental).'},
{n:'Pré-diabetes / síndrome metabólica',cid:'R73.0 / E88.81',sp:'Cardiometabólico',ps:[{v:'CONDUTA NO CONSULTÓRIO',i:['Diagnóstico de PRÉ-DIABETES: glicemia de jejum 100–125 mg/dL, HbA1c 5,7–6,4% ou TOTG 2 h 140–199 (confirmar com 2º exame se assintomático); SÍNDROME METABÓLICA (IDF/NCEP): ≥ 3 de: circunferência ≥ 80 cm (M)/≥ 94 (H) — IDF para sul-americanos; TG ≥ 150; HDL < 50 (M)/< 40 (H); PA ≥ 130/85; glicemia ≥ 100 (ou tratamento para esses); risco de DM2 ~5–10%/ano e CV ↑ 2×','Avaliar: peso/IMC/circunferência, PA, lipidograma, HbA1c, TGO/TGP (MASLD), creatinina, ácido úrico, TSH, urina (RAC), história familiar, SOP (mulher), SAOS, tabagismo, sedentarismo; estratificar risco CV (SBC); ECG se > 40 a ou sintomas','INTERVENÇÃO INTENSIVA NO ESTILO DE VIDA é o tratamento de 1ª linha (DPP: ↓ 58% de progressão para DM — melhor que metformina 31%): perder ≥ 7% do peso, 150 min/semana de atividade moderada + força, dieta mediterrânea/DASH/baixo índice glicêmico, reduzir bebidas açucaradas/ultraprocessados/álcool, sono, cessar tabagismo; programa estruturado/nutricionista/educador físico; reavaliar glicemia/HbA1c a cada 6–12 meses','METFORMINA (ADA: considerar) em alto risco de progressão: IMC ≥ 35, < 60 anos, HbA1c ≥ 6,0%, história de DM gestacional, glicemia de jejum ≥ 110 + HbA1c ↑, SOP — 500 mg → 850 mg 12/12 h (XR se intolerância); B12 anual; aGLP-1/tirzepatida se obesidade (reverte pré-DM — STEP/SURMOUNT); pioglitazona/acarbose são alternativas menos usadas; iSGLT2 não indicado só para pré-DM','Tratar cada componente para a META: PA < 130/80 (IECA/BRA de preferência); LDL conforme risco (estatina se risco intermediário/alto — muitos têm indicação); TG ≥ 150 → estilo de vida (açúcar/álcool), ≥ 500 → fibrato; ácido úrico ↑ assintomático → não tratar com fármaco (dieta); MASLD → FIB-4; SAOS → polissonografia/CPAP; SOP → metformina/ACO/progestágeno conforme desejo reprodutivo; AAS só se prevenção secundária','Seguimento anual (glicemia de jejum + HbA1c, lipidograma, PA, peso, TGO/TGP, creatinina/RAC, TSH se indicado); progressão para DM2 → tratar como DM; rastrear retinopatia só se DM; vacinas']}],casa:[{v:'USO ORAL (estilo de vida é a base — medicamentos conforme indicação)',i:[['Metformina 500 mg (ou 850 mg; XR 500–750 mg) — se alto risco (IMC ≥ 35, < 60 a, HbA1c ≥ 6%, DMG prévio, SOP)','60 comprimidos','Tomar 1 comprimido no jantar por 1–2 semanas, depois 1 no café e 1 no jantar com as refeições (até 850 mg 12/12 h); dosar B12 anualmente'],['Atorvastatina 10–20 mg (20–40 mg se risco alto) — conforme estratificação de risco/LDL','30 comprimidos','Tomar 1 comprimido à noite, uso contínuo'],['Losartana 50 mg (ou enalapril 10 mg) — se PA ≥ 130/80 confirmada (MRPA/MAPA) após mudança de estilo de vida, ou ≥ 140/90','30–60 comprimidos','Tomar 1 comprimido 1–2×/dia'],['Semaglutida/liraglutida/tirzepatida SC — se obesidade (IMC ≥ 30 ou ≥ 27 com comorbidade) e disponível','1 caneta','Conforme protocolo de obesidade (escalonamento mensal)'],['Exames anuais: glicemia de jejum, HbA1c, lipidograma, TGO/TGP, creatinina, urina (RAC), ácido úrico, TSH; TOTG 75 g se dúvida','—','Retorno em 3–6 meses com peso/PA/cintura; exames em 6–12 meses']]}],ori:['Pré-diabetes é um AVISO reversível: perder 5–7% do peso (ex.: 85 kg → perder 4–6 kg) e caminhar 150 min por semana reduzem pela metade a chance de virar diabetes — funciona melhor que remédio; manter por toda a vida','Alimentação: cortar açúcar, refrigerante, sucos (inclusive "natural"), doces, pão branco/massas/arroz branco em excesso, ultraprocessados; preferir verduras, legumes, frutas inteiras (2–3 porções/dia), feijões, grãos integrais, proteínas magras, azeite, oleaginosas; prato: ½ vegetais, ¼ proteína, ¼ carboidrato; comer em horários regulares, devagar; água como bebida principal; álcool mínimo','Atividade física: 30 min de caminhada rápida 5×/semana (ou 150 min/sem) + fortalecimento muscular 2–3×/semana; reduzir o tempo sentado (levantar a cada 1 h); após as refeições, 10–15 min de caminhada ajuda a glicemia','Sono 7–8 h, tratar ronco/apneia, parar de fumar (o maior fator de risco cardiovascular modificável), controlar pressão e colesterol, manejar o estresse; cintura abaixo de 80 cm (mulher)/94 cm (homem) é a meta','Exames a cada 6–12 meses (glicemia e HbA1c) para acompanhar; retorno em 3–6 meses; se metformina: tomar com comida (náusea/diarreia no início melhoram), dosar vitamina B12 anualmente; mulheres com desejo de engravidar/gestantes: informar (rastreio de DM gestacional)'],al:['Sede e urina excessivas, perda de peso sem explicação, visão turva, infecções/feridas que não cicatrizam, candidíase de repetição (pode ter virado diabetes — dosar glicemia)','Dor no peito, falta de ar aos esforços, dor nas pernas ao caminhar, fraqueza/fala alterada súbita (risco cardiovascular) → PS/SAMU','PA ≥ 180/110, dor de cabeça intensa, visão turva; olhos amarelos/dor no fígado; dor abdominal intensa com triglicerídeos muito altos'],ref:'ADA Standards of Care 2024/2025 (Prevention or Delay of Diabetes); SBD — Diretriz 2023/2024 (Pré-diabetes e prevenção do DM2); DPP NEJM 2002 e DPPOS Lancet Diabetes Endocrinol 2015; Finnish DPS NEJM 2001; Da Qing Lancet 2008/2019; IDF Consensus Metabolic Syndrome 2006 / Alberti Circulation 2009 (definição harmonizada); I Diretriz Brasileira de Síndrome Metabólica (SBC 2005) e Diretriz de Prevenção Cardiovascular SBC 2019; Cochrane 2017/2019 (intervenções de estilo de vida e metformina em pré-DM); Knowler; STEP 1/SURMOUNT-1 (reversão de pré-DM com aGLP-1).'},
{n:'Hipotireoidismo (diagnóstico e ajuste)',cid:'E03.9',sp:'Endocrinologia',ps:[{v:'CONDUTA NO CONSULTÓRIO',i:['Diagnóstico: TSH ↑ + T4 livre ↓ = hipotireoidismo primário (tratar sempre); TSH ↑ + T4L normal = SUBCLÍNICO (confirmar em 2–3 meses — 60% normalizam; tratar se TSH ≥ 10, ou TSH 4,5–10 com sintomas/anti-TPO positivo/gestante ou desejo de engravidar/bócio/dislipidemia/IC/depressão; em > 70 anos TSH até 7–8 pode ser normal — não tratar subclínico leve em idosos: TRUST); dosar ANTI-TPO (Hashimoto — causa mais comum; não precisa repetir), lipidograma, hemograma, glicemia; USG de tireoide só se nódulo palpável/bócio assimétrico; excluir: medicamentos (amiodarona, lítio, imunoterapia), pós-tireoidectomia/iodo radioativo, tireoidite subaguda em recuperação, insuficiência adrenal (tratar antes — se suspeita: cortisol)','LEVOTIROXINA — dose: adulto saudável < 60–65 a sem cardiopatia: dose plena 1,6 mcg/kg/dia (peso ideal) ≈ 75–125 mcg; subclínico: 25–75 mcg; idoso/cardiopata/coronariopatia: iniciar 12,5–25 mcg e ↑ 12,5–25 mcg a cada 4–6 semanas (angina/arritmia); gestante: iniciar dose plena e ↑ 25–30% se já em uso ao confirmar gravidez (TSH < 2,5 no 1º tri); tomar em JEJUM 30–60 min antes do café (ou ao deitar ≥ 3 h após o jantar), longe de ferro/cálcio/omeprazol/soja/café (4 h)','AJUSTE: TSH em 6–8 semanas após iniciar/mudar dose ou marca (meta: 0,5–4,0 (adulto); 1–2,5 em gestante/desejo de engravidar; 1–5–6 em > 70 a); TSH alto → ↑ 12,5–25 mcg; TSH suprimido (< 0,1–0,4) → ↓ 12,5–25 mcg (risco de FA/osteoporose); depois TSH anual (ou 6/6 m em idoso/gestante/alteração de peso); TSH persistentemente alto apesar da dose "adequada" = checar ADESÃO/forma de tomar, interações (IBP, sulfato ferroso, cálcio, colestiramina, sucralfato, estrogênio ↑ necessidade), má absorção (celíaca, gastrite atrófica — anti-TPO + anemia → investigar), ganho de peso; não usar T3/T4 combinados nem "tireoide dessecada" de rotina (ATA); não tratar "sintomas" com TSH normal','Sintomas que não melhoram com TSH normalizado (fadiga, ganho de peso): investigar outras causas (depressão, apneia, anemia, deficiência de B12/D, menopausa) — não aumentar a levotiroxina para "sentir-se melhor"; peso: levotiroxina não é para emagrecer','Nódulo/bócio: USG → TI-RADS → PAAF se indicado; Hashimoto com nódulo: mesma conduta; oftalmopatia/sintomas de hipertireoidismo em dose excessiva: reduzir; rastrear outras autoimunidades se clínica (celíaca, B12/anemia perniciosa, Addison, DM1); gestação: TSH + anti-TPO no pré-natal; pós-parto: tireoidite (hiper→hipo) em 5–10%']}],casa:[{v:'USO ORAL',i:[['Levotiroxina sódica 25 / 50 / 75 / 88 / 100 / 112 / 125 / 150 mcg (manter sempre a MESMA marca/laboratório — Puran T4®, Synthroid®, Euthyrox®, Levoid® ou genérico)','30 comprimidos (dose: ___ mcg)','Tomar 1 comprimido TODOS OS DIAS, em JEJUM, 30–60 min antes do café da manhã (ou ao deitar, ≥ 3 h após a última refeição), só com água; não tomar junto de café, leite, ferro, cálcio, omeprazol, soja, fibras (intervalo de 4 h); se esquecer, tomar no mesmo dia ou dobrar no dia seguinte'],['Exames de controle: TSH (± T4 livre) em 6–8 semanas após iniciar/ajustar; depois TSH 1×/ano (6/6 meses se gestante/idoso/mudança de peso ou de medicamentos)','—','Colher TSH pela manhã, ANTES de tomar a levotiroxina do dia (ou informar o horário); levar o resultado ao retorno'],['Anti-TPO, lipidograma, hemograma, glicemia (no diagnóstico); B12/ferritina se anemia; USG só se nódulo/bócio','—','Uma vez (anti-TPO não precisa repetir)']]}],ori:['A levotiroxina repõe o hormônio que a tireoide não produz — o tratamento geralmente é para a vida toda e NÃO pode ser interrompido quando os sintomas melhoram ou o exame "normaliza"; o efeito demora 4–8 semanas; o ajuste é feito pelo TSH (exame), não pelos sintomas do dia','Como tomar: em jejum, 30–60 min antes do café, com água, sempre no mesmo horário e com a mesma marca (trocar de marca/genérico pode alterar a dose — se trocar, repetir TSH em 6–8 semanas); separar 4 h de: ferro, cálcio, omeprazol/pantoprazol, antiácidos, vitaminas, soja, café, fibras; informar ao médico qualquer remédio novo','Gestante ou planejando engravidar: avise IMEDIATAMENTE — a dose costuma precisar aumentar 25–30% no início da gravidez (TSH < 2,5) e o hormônio é essencial para o bebê; amamentação: pode usar normalmente','Peso: a levotiroxina não emagrece e NÃO deve ser usada/aumentada para isso (risco de arritmia e osteoporose); ganho de peso com TSH normal tem outras causas','Exames: TSH em 6–8 semanas após cada mudança e depois 1×/ano; retorno com o resultado; sintomas de excesso (palpitação, tremor, insônia, perda de peso, suor, diarreia, nervosismo) ou de falta (cansaço, frio, prisão de ventre, pele seca, inchaço, sonolência) → antecipar o TSH'],al:['Palpitações fortes/irregulares, dor no peito, falta de ar, tremor, perda de peso rápida, insônia intensa, diarreia (dose excessiva ou hipertireoidismo) → avaliar/reduzir','Sonolência extrema, confusão, hipotermia, inchaço generalizado, respiração lenta (coma mixedematoso — raro; idoso que parou o remédio/infecção) → PS','Nódulo no pescoço que cresce, rouquidão persistente, dificuldade para engolir/respirar (avaliar com USG)','Gestante: qualquer dúvida de dose/atraso de TSH'],ref:'ATA Guidelines for the Treatment of Hypothyroidism 2014 (Jonklaas); ETA Guideline Subclinical Hypothyroidism 2013 (Pearce); ATA Thyroid and Pregnancy 2017 (Alexander); SBEM — Consenso Brasileiro para Diagnóstico e Tratamento do Hipotireoidismo 2013 e Atualização 2020/2022; TRUST NEJM 2017 (Stott — subclínico em idosos); Feller JAMA 2018 (meta-análise subclínico); Garber Endocr Pract 2012 (AACE/ATA); Cochrane 2007 (subclínico); Chaker Lancet 2017 (revisão).'},
{n:'Hiperuricemia / gota crônica (tratamento de manutenção)',cid:'M10.9 / E79.0',sp:'Reumatologia',ps:[{v:'CONDUTA NO CONSULTÓRIO',i:['HIPERURICEMIA ASSINTOMÁTICA (AU > 7 mg/dL sem crise/tofo/litíase): NÃO tratar com fármaco (ACR/EULAR) — estilo de vida + revisar diuréticos; exceção discutível: AU > 9–10 persistente, DRC/litíase recorrente (nefrologia)','INDICAÇÃO DE HIPOURICEMIANTE (treat-to-target): ≥ 2 crises/ano, tofos, erosões radiográficas, ≥ 1 crise + DRC ≥ 3 ou AU ≥ 9 ou urolitíase; iniciar durante ou 2 semanas após a crise (com cobertura anti-inflamatória) — ALOPURINOL 1ª linha: 100 mg/dia (50 mg se TFG < 30), ↑ 100 mg a cada 2–5 semanas até META de ácido úrico < 6 mg/dL (< 5 se tofos/grave), dose usual 300–600 mg (máx. 800–900); pode exceder 300 mg mesmo na DRC com titulação lenta; FEBUXOSTATE 40–80 mg (2ª linha: intolerância/alergia ao alopurinol, DRC — cautela em DCV: CARES; FAST não confirmou ↑ risco); uricosúricos (benzbromarona 50–100 mg — hepatotoxicidade; probenecida) se excreção baixa/sem litíase/TFG > 50; pegloticase (refratária grave — indisponível)','PROFILAXIA DE CRISES ao iniciar/titular (3–6 meses, até 3–6 meses após atingir a meta/sumir tofos): COLCHICINA 0,5 mg 1×/dia (12/12 h se > 70 kg/função renal normal; 0,5 mg em dias alternados se TFG 30–50; evitar < 30 ou com claritromicina/ciclosporina/estatina alta dose — miopatia) — ou naproxeno 250 mg 12/12 h/prednisona 5–7,5 mg se contraindicação','Monitorar AU a cada 2–5 semanas na titulação, depois a cada 6 meses; creatinina/TFG, TGO/TGP, hemograma; HLA-B*5801 antes do alopurinol em asiáticos (Han, coreanos, tailandeses) e afrodescendentes (risco de síndrome de hipersensibilidade — DRESS/SJS: rash + febre + eosinofilia nas primeiras 8–12 semanas → suspender imediatamente); não suspender o hipouricemiante durante crises; ajustar na DRC','COMORBIDADES (gota = marcador cardiometabólico): HAS (preferir LOSARTANA — uricosúrica; anlodipino; evitar tiazídico/furosemida se possível), DM2 (iSGLT2 ↓ AU e crises), dislipidemia (fenofibrato ↓ AU; atorvastatina leve), obesidade, MASLD, DRC, SAOS; AAS baixa dose: manter se indicação CV; avaliar RX das articulações/USG (duplo contorno) se dúvida; artrocentese com cristais confirma'],}],casa:[{v:'USO ORAL — MANUTENÇÃO (treat-to-target: ácido úrico < 6 mg/dL)',i:[['Alopurinol 100 mg (comprimidos de 100 e 300 mg)','30–60 comprimidos','Começar com 1 comprimido de 100 mg 1×/dia após o café; AUMENTAR 100 mg a cada 2–4 semanas conforme o ácido úrico (meta < 6; dose habitual 300–600 mg/dia, ex.: 1 cp de 300 mg + 1 de 100 mg); uso contínuo, inclusive durante crises; suspender e procurar atendimento se manchas na pele/febre/coceira nas primeiras semanas'],['OU Febuxostate 40 mg (↑ para 80 mg se AU > 6 após 2–4 semanas) — se alergia/intolerância ao alopurinol ou DRC (evitar se IAM/AVC/IC recentes)','30 comprimidos','Tomar 1 comprimido 1×/dia, com ou sem alimento'],['+ Colchicina 0,5 mg — PROFILAXIA de crises nos primeiros 3–6 meses de tratamento (até 6 meses após atingir a meta)','30–60 comprimidos','Tomar 1 comprimido 1×/dia (ou de 12/12 h se > 70 kg e rim normal; dias alternados se insuficiência renal); suspender se diarreia intensa/dor muscular'],['Naproxeno 500 mg (ou prednisona 20 mg) — para CRISE (ter em casa; iniciar nas primeiras 24 h)','14 comprimidos','Crise: naproxeno 1 cp de 12/12 h por 5–7 dias (ou prednisona 30–40 mg/dia por 5 dias) — OU colchicina 1 mg + 0,5 mg após 1 h, depois 0,5 mg 12/12 h; NÃO parar o alopurinol'],['Losartana 50 mg — se hipertenso (↓ ácido úrico; substituir hidroclorotiazida quando possível)','30–60 comprimidos','Tomar 1 comprimido 1–2×/dia'],['Exames de controle: ácido úrico a cada 2–4 semanas até a meta (depois 6/6 meses), creatinina, TGO/TGP, hemograma; HLA-B*5801 antes do alopurinol se ascendência asiática/africana','—','Levar ao retorno em 4 semanas']]}],ori:['O objetivo é manter o ácido úrico ABAIXO de 6 mg/dL para dissolver os cristais e acabar com as crises — isso leva meses a anos e exige tomar o remédio TODOS OS DIAS, para sempre (parar = crises voltam em 1–2 anos); nos primeiros meses as crises podem até aumentar (cristais se mobilizando) — por isso a colchicina preventiva; NÃO parar o alopurinol durante uma crise','Alimentação: evitar/reduzir cerveja (com ou sem álcool), destilados, refrigerantes e sucos com açúcar/frutose, carnes vermelhas e vísceras (fígado, miúdos), frutos do mar (camarão, sardinha, anchova), caldos/embutidos; moderar carnes magras/peixes; liberados e protetores: laticínios desnatados, café, cerejas, vegetais (inclusive os "ricos em purina" como espinafre/feijão — não aumentam risco), água 2–3 L/dia; vinho moderado é menos pior que cerveja; perder peso devagar (jejum/dieta radical precipita crise)','Crise: iniciar o anti-inflamatório/colchicina nas primeiras horas (ter em casa), repouso, gelo 20 min 3–4×/dia, elevar a articulação; não usar AAS em dose analgésica (↑ ácido úrico); procurar atendimento se febre alta/articulação muito quente (descartar infecção)','Informar que tem gota antes de receber diuréticos (hidroclorotiazida/furosemida), AAS, ciclosporina, pirazinamida; preferir losartana para pressão; controlar peso, pressão, diabetes, colesterol (gota aumenta risco cardiovascular e renal)','Retorno em 4 semanas com ácido úrico/creatinina para ajustar a dose; depois a cada 3–6 meses; reumatologista se tofos, erosões, falha de 2 fármacos, DRC avançada, dúvida diagnóstica'],al:['Manchas vermelhas/bolhas na pele, coceira, febre, inchaço de face, feridas na boca, olhos vermelhos nas primeiras 8–12 semanas de alopurinol → PARAR IMEDIATAMENTE e procurar PS (reação grave — DRESS/Stevens-Johnson)','Diarreia intensa, vômitos, fraqueza/dor muscular, formigamentos com colchicina (toxicidade — suspender)','Articulação muito quente, vermelha, febre alta, calafrios, toxemia (artrite séptica — não é só gota) → PS','Dor lombar em cólica/sangue na urina (cálculo renal), urina diminuída, inchaço (função renal)','Dor no peito, falta de ar (febuxostate — risco CV; gota = risco CV)'],ref:'ACR Guideline for the Management of Gout 2020 (FitzGerald); EULAR Recommendations 2016 (Richette) e 2020 (diagnóstico); BSR 2017 (Hui); SBR — Diretrizes de Gota 2019/2021 (Sociedade Brasileira de Reumatologia); Stamp Ann Rheum Dis 2017 (alopurinol acima de 300 mg na DRC); CARES NEJM 2018 e FAST Lancet 2020 (febuxostate e risco CV); Hershfield Clin Pharmacol Ther 2013 (HLA-B*5801); Cochrane 2014 (alopurinol) e 2021 (colchicina profilaxia); Dalbeth Lancet 2021 (revisão); Choi NEJM 2004/BMJ 2008 (dieta/álcool).'},
{n:'Anemia ferropriva (adulto) — investigação e reposição',cid:'D50.9',sp:'Clínica geral',ps:[{v:'CONDUTA NO CONSULTÓRIO',i:['Confirmar: Hb < 12 (M) / < 13 (H); microcítica/hipocrômica (VCM < 80, HCM ↓, RDW ↑), ferritina < 30 ng/mL (< 100 se inflamação/DRC/IC com saturação < 20%), saturação de transferrina < 16–20%, CTLF ↑; reticulócitos ↓; excluir talassemia menor (Mentzer < 13, RDW normal, ferritina normal → eletroforese de Hb), anemia de doença crônica (ferritina ↑, saturação ↓, PCR ↑), B12/folato (macro/mista), DRC (creatinina), hipotireoidismo','INVESTIGAR A CAUSA (obrigatório): MULHER em idade fértil: menorragia (ciclo > 7 d, coágulos, > 80 mL — avaliar mioma/adenomiose/coagulopatia/DIU de cobre; USG TV), gestações, dieta (vegetariana), doadora de sangue; HOMEM ou MULHER PÓS-MENOPAUSA (ou pré-menopausa sem causa clara/sintomas GI/≥ 45–50 a/história familiar): ENDOSCOPIA DIGESTIVA ALTA + COLONOSCOPIA (câncer colorretal/gástrico, úlcera, angiodisplasia, DII — BSG 2021: mesmo sem sangue nas fezes), pesquisa de H. pylori e biópsia duodenal (doença celíaca — antitransglutaminase IgA + IgA total em todos), gastrite atrófica (B12/gastrina), uso de AINE/AAS/anticoagulante, parasitoses (EPF em áreas endêmicas — ancilóstomo), cirurgia bariátrica/gastrectomia, hematúria/hemoglobinúria, doença renal, hemólise; sangue oculto nas fezes negativo NÃO exclui; cápsula endoscópica se EDA/colono normais e persistência','REPOSIÇÃO ORAL (1ª linha): 60–120 mg de ferro ELEMENTAR 1×/dia ou em DIAS ALTERNADOS (↑ absorção, ↓ efeitos GI — Stoffel 2017/2020); sulfato ferroso 300–325 mg (= 60–65 mg Fe) 1 cp em jejum/dias alternados; alternativas se intolerância: ferro polimaltosado 100 mg/cp, bisglicinato quelato 30 mg (melhor tolerância), fumarato; vitamina C/suco cítrico ↑ absorção; evitar com chá/café/leite/cálcio/IBP (2 h); resposta: reticulócitos ↑ em 7–10 d, Hb ↑ ≥ 1–2 g/dL em 2–4 semanas; manter 3–6 meses após normalizar a Hb (ferritina > 50–100)','FERRO ENDOVENOSO (ambulatório/hospital-dia): intolerância/falha oral (↑ Hb < 1 g/dL em 4 sem com adesão), má absorção (celíaca não tratada, bariátrica, gastrectomia, DII ativa), perda contínua > capacidade oral, anemia grave (Hb < 8) com sintomas/próximo de cirurgia, DRC em diálise/IC (ferritina < 100–300/sat < 20%), 2º–3º trimestre de gestação com intolerância, necessidade rápida: carboximaltose férrica 500–1.000 mg em 1–2 infusões (déficit de Ganzoni ou tabela simplificada por peso/Hb), sacarato de hidróxido férrico 200 mg EV 1–3×/sem (SUS), derisomaltose; hipofosfatemia com carboximaltose (dosar P se sintomas/repetidas)','TRANSFUSÃO: só se instabilidade hemodinâmica/isquemia/Hb < 7 com sintomas (não para "repor ferro"); Hb < 7–8 assintomática crônica → ferro EV + investigação urgente','Seguimento: hemograma + reticulócitos em 2–4 semanas; hemograma + ferritina em 3 meses e ao fim do tratamento; recorrência → reinvestigar; tratar causa (menorragia: ACO/SIU-LNG/ácido tranexâmico; H. pylori; celíaca — dieta; parasitas — albendazol; suspender AINE); gestante: ferro profilático 40 mg/dia + ácido fólico']}],casa:[{v:'USO ORAL',i:[['Sulfato ferroso 300–325 mg comprimido/drágea (= 60–65 mg de ferro elementar) — ou Sulfato ferroso 40 mg Fe (comprimido 109 mg)','30–60 comprimidos','Tomar 1 comprimido (60–65 mg Fe) 1×/dia EM DIAS ALTERNADOS (ou todos os dias se preferir), em jejum ou 1 h antes do almoço, com suco de laranja/limão; se intolerância, tomar após uma refeição pequena; manter por 3–6 MESES após a hemoglobina normalizar; fezes escuras são normais'],['OU Ferro polimaltosado 100 mg (Noripurum® comprimido mastigável/oral) ou Ferro bisglicinato quelato 30 mg (Neutrofer® — 1–2 cp) — se intolerância ao sulfato','30 comprimidos','Tomar 1 comprimido 1×/dia (polimaltosado pode ser com alimento; quelato em jejum); mesma duração'],['Vitamina C 500 mg (ou suco cítrico) — opcional','30 comprimidos','Tomar junto com o ferro'],['Ácido fólico 5 mg + Vitamina B12 (se deficiência associada/dieta restrita/gastrectomia/metformina)','30 comprimidos','Ácido fólico 1 cp/dia por 3 meses; B12 conforme nível (cianocobalamina 1.000 mcg VO/dia ou IM semanal × 4 → mensal)'],['Albendazol 400 mg (área endêmica/EPF positivo)','1 comprimido','Dose única (repetir em 6 meses se área endêmica)'],['Omeprazol: REDUZIR/suspender se possível (↓ absorção de ferro) — discutir','—','—'],['Exames: hemograma + reticulócitos em 2–4 semanas; hemograma + ferritina + saturação de transferrina em 3 meses; EXAMES DE INVESTIGAÇÃO conforme indicação: EDA + colonoscopia (homem/pós-menopausa/≥ 45–50 a/sintomas GI), antitransglutaminase IgA + IgA total, H. pylori, EPF ×3, urina I, TSH, creatinina, B12/folato, eletroforese de Hb (se VCM baixo + ferritina normal), USG transvaginal (menorragia)','—','Levar ao retorno']]}],ori:['A anemia por falta de ferro sempre tem uma CAUSA (perda de sangue — menstruação intensa, intestino/estômago —, má absorção ou dieta) e ela precisa ser investigada e tratada, não só o ferro reposto; os exames pedidos (endoscopia/colonoscopia, exames de fezes/urina/sangue) são parte do tratamento — não deixe de fazer','Como tomar o ferro: 1 comprimido em jejum ou 1 h antes de uma refeição, com suco de laranja/limão (vitamina C ajuda), em DIAS ALTERNADOS (absorve melhor e dá menos enjoo); evitar junto com leite/queijo/iogurte, café, chá, mate, refrigerante, antiácidos/omeprazol, cálcio (separar 2 h); se der náusea/cólica, tomar após uma refeição leve ou trocar o tipo de ferro (avisar); fezes escuras/prisão de ventre são esperadas (fibras/água); manter por 3–6 meses APÓS normalizar — para encher os estoques (ferritina); guardar longe de crianças (intoxicação grave)','Alimentação rica em ferro: carnes vermelhas, fígado (1×/sem), frango, peixe, gema de ovo; feijão, lentilha, grão-de-bico, folhas verde-escuras, castanhas — sempre com uma fonte de vitamina C (laranja, acerola, limão, tomate) e longe de café/chá/leite; beterraba NÃO é boa fonte; vegetarianos/veganos: planejar com nutricionista (ferro pode precisar ser contínuo) e checar B12','Menstruação muito intensa (trocar absorvente a cada 1–2 h, coágulos, > 7 dias, anemia recorrente): ginecologista — há tratamentos (anticoncepcional, DIU hormonal, ácido tranexâmico, tratar mioma); doadores de sangue frequentes: espaçar','Retorno em 4 semanas com hemograma (a hemoglobina deve subir ≥ 1 g/dL); depois em 3 meses; se não melhorar: rever adesão/tolerância, causa não tratada, má absorção → ferro na veia; sintomas de melhora em 1–2 semanas (energia), cabelo/unhas em meses'],al:['Falta de ar/cansaço aos mínimos esforços, palpitações, dor no peito, tontura/desmaio, palidez intensa (anemia grave) → PS (pode precisar de transfusão/ferro EV)','Fezes PRETAS que não sejam pelo ferro (pegajosas, fétidas — melena) ou com sangue vivo em quantidade, vômito com sangue → PS','Perda de peso, dor abdominal persistente, mudança do hábito intestinal, dificuldade para engolir, sangramento vaginal fora do período/pós-menopausa, nódulos, febre/suores noturnos, sangue na urina → investigar com urgência','Vômitos/dor abdominal intensa com uso de ferro (intoxicação — sobretudo criança que ingeriu); reação alérgica/falta de ar após ferro na veia'],ref:'BSG Guidelines for the Management of Iron Deficiency Anaemia in Adults 2021 (Snook); AGA Clinical Practice Guidelines on Gastrointestinal Evaluation of IDA 2020 (Ko); ASH/BSH; OMS 2011/2020 (definições e ferro); Stoffel Lancet Haematol 2017 e 2020 (dias alternados/dose única); Cochrane 2019 (ferro EV × oral); Camaschella NEJM 2015/2019 (revisão); Auerbach Am J Hematol 2016 (ferro EV); ABHH — Diretriz de Anemia Ferropriva 2018; FIGO 2018 (sangramento uterino anormal); Ganzoni 1970 (déficit de ferro).'},
{n:'Refluxo gastroesofágico / dispepsia crônica (ambulatório)',cid:'K21.0 / K30',sp:'Gastroenterologia',ps:[{v:'CONDUTA NO CONSULTÓRIO',i:['Sintomas típicos (pirose + regurgitação ≥ 2×/semana) sem alarme → DIAGNÓSTICO CLÍNICO + teste terapêutico com IBP por 4–8 semanas (resposta = DRGE provável); SINAIS DE ALARME → EDA antes: disfagia/odinofagia, perda de peso, anemia/sangramento, vômitos persistentes, massa, idade ≥ 50–60 a com sintomas novos, história familiar de câncer gástrico/esofágico, falha do IBP em 8 semanas, sintomas de longa data (> 5–10 a — rastrear Barrett em homem > 50 a, obeso, tabagista, branco); dispepsia (epigastralgia/plenitude) sem alarme < 60 a → TESTAR E TRATAR H. pylori (teste respiratório ureia-13C ou antígeno fecal — suspender IBP 2 semanas e antibiótico 4 semanas antes) e IBP se negativo (dispepsia funcional — Roma IV)','IBP: dose padrão 1×/dia 30–60 min ANTES do café (omeprazol 20–40 / pantoprazol 40 / esomeprazol 40 / lansoprazol 30 / rabeprazol 20 / vonoprazana 20 mg — bloqueador ácido competitivo de K+, mais potente, para esofagite grave/refratária); sintomas noturnos/esofagite C–D/Barrett → 2×/dia (antes do café e do jantar); esofagite erosiva: 8 semanas então reduzir; sem esofagite (DRNE): MENOR DOSE EFICAZ, "sob demanda" ou intermitente após controle; desmame gradual (↓ 50% por 1–2 sem) para evitar rebote ácido; uso prolongado só com indicação (esofagite grave, Barrett, estenose, AINE + risco) — riscos modestos: ↓ Mg/B12/ferro, fratura, C. difficile, nefrite intersticial, pneumonia','H. PYLORI positivo: ERRADICAR (IV Consenso Brasileiro 2018 / Maastricht VI): IBP dose dupla + amoxicilina 1 g + claritromicina 500 mg 12/12 h por 14 DIAS (resistência à claritromicina < 15% no Brasil — preferida) ou terapia quádrupla com bismuto (IBP + bismuto 120 mg 4×/d + tetraciclina 500 mg 4×/d + metronidazol 400–500 mg 3×/d — 10–14 d; 1ª linha se alergia a penicilina/macrolídeo recente) ou concomitante (IBP + amoxicilina + claritromicina + metronidazol 14 d); confirmar erradicação ≥ 4 semanas após (teste respiratório/antígeno fecal — não sorologia); falha → quádrupla com bismuto ou levofloxacino 500 mg + amoxicilina + IBP 14 d; tratar família? só se sintomática/indicação','Adjuvantes: procinético (domperidona 10 mg antes das refeições — náusea/plenitude; QT) por tempo limitado; alginato (Gaviscon®) após refeições/noite para "acid pocket"; antiácidos para resgate; sucralfato na gestação; evitar bloqueadores H2 contínuos (taquifilaxia — útil famotidina 20–40 mg à noite para escape noturno); dispepsia funcional refratária → amitriptilina 10–25 mg à noite (neuromodulador), buspirona, TCC; baclofeno 5–10 mg 3×/d (refluxo/arroto) em refratários','REFRATÁRIO (sem resposta a IBP 2×/dia por 8–12 semanas, adesão correta): EDA (esofagite eosinofílica — biópsias; acalasia; úlcera), pHmetria-impedanciometria sem IBP (confirmar refluxo — 30–40% não têm), manometria; considerar cirurgia (fundoplicatura) se refluxo comprovado, grande hérnia, regurgitação volumosa, jovem que não quer IBP contínuo — gastro/cirurgia; sintomas extraesofágicos (tosse, rouquidão, asma, globus) raramente respondem a IBP isolado — investigar outras causas','Modificações comprovadas: perder peso (maior impacto), elevar a cabeceira 15–20 cm (calço — não travesseiros), não deitar por 2–3 h após comer, cessar tabagismo, reduzir álcool/refeições volumosas e gordurosas/tarde da noite; alimentos individualmente (café, chocolate, menta, cítricos, tomate, condimentos, refrigerante) — evitar só se desencadeiam; revisar medicamentos (AINE, bisfosfonatos, BCC, nitratos, anticolinérgicos, teofilina, antidepressivos)']}],casa:[{v:'USO ORAL',i:[['Omeprazol 20 mg (ou 40 mg) / Pantoprazol 40 mg / Esomeprazol 40 mg (ou Vonoprazana 20 mg se esofagite grave/refratária)','30–60 comprimidos','Tomar 1 comprimido em JEJUM, 30–60 min antes do café da manhã, 1×/dia por 4–8 semanas (2×/dia — antes do café e do jantar — se sintomas noturnos/esofagite importante); depois reduzir para a menor dose que controle ou usar só nos dias de sintoma'],['Alginato de sódio + bicarbonato (Gaviscon® líquido/sachê) ou Hidróxido de alumínio/magnésio','1 frasco / 20 sachês','Tomar 10–20 mL 30 min após as refeições e ao deitar se azia, até 4×/dia (alívio rápido; não substitui o IBP)'],['Domperidona 10 mg — se náusea/empachamento/plenitude (até 4 semanas)','30 comprimidos','Tomar 1 comprimido 15–30 min antes do café, almoço e jantar (evitar se QT longo/arritmia)'],['ERRADICAÇÃO DE H. PYLORI (se teste positivo) — 14 dias: Omeprazol 20 mg (ou outro IBP em dose dupla) + Amoxicilina 500 mg + Claritromicina 500 mg','28 cp de IBP + 56 cápsulas de amoxicilina + 28 cp de claritromicina','Omeprazol 20 mg (ou 40 mg) de 12/12 h antes do café e do jantar + Amoxicilina 2 cápsulas (1 g) de 12/12 h + Claritromicina 1 cp (500 mg) de 12/12 h, após as refeições, por 14 DIAS seguidos — não interromper (gosto metálico/diarreia são comuns); probiótico opcional; repetir o teste respiratório/antígeno fecal ≥ 4 semanas após o fim (e ≥ 2 semanas sem IBP)'],['Famotidina 40 mg — opcional para escape noturno (não contínuo)','30 comprimidos','Tomar 1 comprimido ao deitar nos dias com azia noturna'],['Amitriptilina 25 mg (ou nortriptilina 10–25 mg) — dispepsia funcional/dor epigástrica refratária a IBP (neuromodulador)','30 comprimidos','Tomar ½–1 comprimido à noite por ≥ 8–12 semanas'],['Exames conforme indicação: teste respiratório ureia-13C ou antígeno fecal para H. pylori (suspender IBP 14 dias e antibiótico 4 semanas antes); hemograma/ferritina; EDA (se alarme/≥ 50–60 a/falha); pHmetria-impedanciometria/manometria (refratário)','—','Levar ao retorno em 4–8 semanas']]}],ori:['O IBP (omeprazol etc.) funciona melhor tomado em JEJUM, 30–60 min antes do café (e antes do jantar se 2×/dia), todos os dias durante o período prescrito; depois de melhorar, a ideia é usar a MENOR dose possível ou só quando tiver sintomas — não é para ficar "para sempre" sem indicação; ao parar, reduzir aos poucos (a azia pode voltar por 1–2 semanas — rebote)','Medidas que mais ajudam: perder peso (barriga comprime o estômago), não deitar nas 2–3 h após comer, jantar mais cedo e leve, elevar a CABECEIRA da cama 15–20 cm com calços/bloco sob os pés da cama (travesseiros não funcionam), dormir do lado esquerdo, parar de fumar, reduzir álcool, refeições menores e mais frequentes, mastigar bem, não usar roupas apertadas, não fazer exercício logo após comer','Alimentos: observar os SEUS gatilhos (não precisa proibir tudo): os mais comuns são café, chocolate, hortelã/menta, frituras/gorduras, pimenta/condimentos, cítricos/tomate, refrigerante/gás, álcool, cebola/alho; chá/água morna/mascar chiclete após refeições podem aliviar','Evitar anti-inflamatórios (ibuprofeno, diclofenaco, nimesulida, AAS) — causam gastrite/úlcera; se precisar de analgésico: dipirona/paracetamol; informar outros remédios (alguns pioram o refluxo); H. pylori: completar os 14 dias mesmo com efeitos (gosto ruim, diarreia) e repetir o teste depois para confirmar que eliminou — a bactéria aumenta o risco de úlcera e câncer gástrico','Retorno em 4–8 semanas: se melhorou → reduzir/manter sob demanda; se não melhorou (adesão correta) → endoscopia/exames; refluxo não causa infarto, mas a dor no peito pode ser do coração — na dúvida, PS'],al:['Dificuldade ou dor para ENGOLIR (comida "parando"), emagrecimento sem querer, vômitos frequentes, vômito com sangue ou "borra de café", fezes pretas, anemia/cansaço, massa/dor abdominal persistente, icterícia → endoscopia URGENTE/PS','Dor no peito em aperto que aparece com esforço, irradia para braço/mandíbula, com suor frio/falta de ar — pode ser INFARTO, não azia → SAMU 192','Sintomas que não melhoram após 8 semanas de tratamento correto, ou que voltam imediatamente ao reduzir o IBP; sintomas novos após os 50–60 anos; engasgos/tosse noturna/pneumonias de repetição (aspiração); rouquidão persistente > 3 semanas'],ref:'ACG Clinical Guideline GERD 2022 (Katz); AGA Clinical Practice Update 2022 (Yadlapati — IBP: desprescrição/uso); Lyon Consensus 2.0 2023 (diagnóstico de DRGE); ACG/CAG Dyspepsia 2017 (Moayyedi); Roma IV (Stanghellini 2016); IV Consenso Brasileiro sobre H. pylori 2018 (Coelho — Arq Gastroenterol) e Maastricht VI/Florence 2022 (Malfertheiner); FBG — Consenso Brasileiro DRGE 2023; Cochrane 2007 (IBP × H2 × procinéticos), 2016 (H. pylori erradicação na dispepsia — NNT 12), 2023 (terapias de erradicação); Ness-Jensen Clin Gastroenterol Hepatol 2016 (estilo de vida — revisão sistemática); Ford Lancet 2020 (dispepsia funcional); Graham 2024 (vonoprazana).'},
];
